# Check all fields for clues
for k, v in e.items():
    if k == 'spec':
        # Check spec sub-fields
        if isinstance(v, dict):
            for sk, sv in v.items():
                if sk == 'command':
                    print(f'spec.command: {sv}')
                elif sk == 'steps':
                    for step in sv:
                        cmd = step.get('command','')
                        if 'benchmark' in cmd or 'eval' in cmd:
                            print(f'eval command: {cmd[:500]}')
                else:
                    print(f'spec.{sk}: {sv}')
    elif k != 'metrics':
        val = str(v)[:200]
        print(f'{k}: {val}')
